/***/ "./node_modules/raw-loader/index.js!./src/app/Components/ExamContainer/subject-specific-instruction/subject-specific-instruction.component.html":
/*!*********************************************************************************************************************************************!*\
  !*** ./node_modules/raw-loader!./src/app/Components/ExamContainer/subject-specific-instruction/subject-specific-instruction.component.html ***!
  \*********************************************************************************************************************************************/
/*! no static exports found */
/***/ (function(module, exports) {

module.exports = "<div class=\"container mt-4 mb-3\">\n    <div class=\"col-sm-12\">\n        <div style=\"height: 91%; width: 100%; overflow: auto;\">\n            <div style=\"text-align: center;\"><span style=\"font-size:22px;\"><strong><u>Paper Specific\n                            Instructions</u></strong></span></div> <br>\n            <br>\n            <div style=\"text-align: center;\"><strong><span style=\"background-color:#FFFF00;\">\n                        {{user?.courseCode}}&nbsp; {{user?.courseName}}\n                    </span></strong></div>\n            <p style=\"text-align:left;\"><em>Duration</em> : <strong>{{user?.duration}} Minutes </strong><span\n                    style=\"float:right;\"><em>Total Marks</em> : <strong>{{user?.totalMark}}</strong></span></p>\n            <strong>Read the\n                following instructions carefully</strong><br>\n            <ol>\n                <li>Please go through the various question palette symbols and understand their meanings before starting the\n                    examination.</li>\n            </ol>\n            <ol>\n                <li value=\"2\">The question paper consists of<strong> Multiple Choice Questions (MCQ)</strong>.\n                    <br> <br> \n                    a) Multiple choice type questions have four\n                    choices, out of which only <strong>ONE</strong> is the correct answer. Select the answer\n                    by clicking on the radio button placed before the choice, with the help of the mouse.<br> \n                </li>\n            </ol>\n            <ol>\n                <li value=\"3\">All those questions that are not attempted will carry zero marks. There will be no\n                    negative marking for MCQ questions.</li>\n            </ol>\n            <ol>\n                <li value=\"4\">Your answers will be saved on the server periodically and also at the end of the\n                    examination. The examination will <strong>stop automatically</strong> at the end of\n                    <strong>{{user?.duration}} Minutes.</strong></li>\n            </ol>\n            <ol>\n                <li value=\"5\">You are not allowed to leave the examination hall until the completion of the examination.</li>\n            </ol>\n            <ol>\n                <li value=\"6\">Charts, graph sheets, calculators and mathematical tables are NOT allowed in the\n                    examination hall.</li>\n            </ol>\n        </div>\n        <button (click)=\"Previous()\" matTooltip=\"Previous\" mat-mini-fab color=\"accent\" class=\"bottomButton\">\n            <mat-icon>arrow_back</mat-icon>\n        </button>\n        <div class=\"row\">\n            <mat-card>\n                <small class=\"font-weight-bold\">\n                    <mat-checkbox [(ngModel)]=\"checked\" color=\"primary\">\n                    </mat-checkbox> I have read and understood the instructions.\n                    All computer hardware allotted to me are in proper\n                    working condition. I declare that I am not in possession of / not wearing / not carrying any\n                    prohibited gadget like mobile phone, bluetooth devices etc. /any prohibited material with me into\n                    the Examination Hall.I agree that in case of not adhering to the instructions, I shall be liable to\n                    be debarred from this Test and/or to disciplinary action, which may include ban from future Tests /\n                    Examinations.\n                </small>\n                <div class=\"row p-2 d-flex justify-content-center\">\n                    <button [disabled]=\"!checked || !((dataService?.examStartAndTimer | async)?.isProgress)\" (click)=\"Proceed()\" matTooltip=\"Start Examination\" mat-raised-button\n                        class=\"Submit\">\n                        I am ready to begin\n                    </button>\n                </div>\n            </mat-card>\n        </div>\n        \n    </div>\n</div>"

/***/ }),

